/* Read-only Google Merchant Center feed for the approved public SEO projection.
   This is generated by the existing SEO publisher; no checkout or database writes. */
const UUID=/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const IMAGE=/^[0-9a-f-]{36}\/[^/\\.][A-Za-z0-9_.-]*\.(?:jpe?g|png|webp|avif)$/i;
const ALLOWED=new Set(["food_drinks","groceries","dry_goods","bookshop","hardware","garments_clothes_footwear","jewelry","electronics_bcfe08f"]);
const BASE="https://dzdciuqkqixwutvtfotj.supabase.co/storage/v1/object/public/seller-product-media/";
function clean(s,max){return typeof s==="string"?s.replace(/[\u0000-\u001f\u007f]/g," ").replace(/\s+/g," ").trim().slice(0,max):"";}
function xml(s){return String(s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&apos;"}[c]));}
function media(p){if(typeof p!=="string"||!IMAGE.test(p)||p.includes(".."))return null;return BASE+p.split("/").map(encodeURIComponent).join("/");}
function money(n){return typeof n==="number"&&Number.isFinite(n)&&n>0&&Math.round(n*100)===n*100?n.toFixed(2)+" KES":null;}
export function merchantItems(rows){
 if(!Array.isArray(rows)||rows.length>10000)throw Error("Invalid Merchant catalogue");
 const found=new Set(),items=[];
 for(const p of rows){
  if(!p||typeof p.id!=="string"||!UUID.test(p.id)||found.has(p.id))throw Error("Invalid or duplicate product id");
  found.add(p.id);
  // The read-only public RPC already checks active seller, subscription, category and approval.
  // Recheck publishable fields; never guess complex or promotional prices.
  if(!ALLOWED.has(p.category)||p.availability!=="available"||!Array.isArray(p.variants)||p.variants.length)continue;
  const title=clean(p.name,150),desc=clean(p.description,5000);
  const price=money(p.current_price_kes);
  if(!title||!desc||!price||p.regular_price_kes!==p.current_price_kes)continue;
  const image=media(p.image_path);
  if(!image)continue;
  items.push({id:p.id,title,description:desc,price,image,link:"https://leogo.co.ke/seo-catalogue/products/"+p.id+"/"});
 }
 return items.sort((a,b)=>a.id.localeCompare(b.id));
}
export function merchantFeed(rows){
 const items=merchantItems(rows);
 const nodes=items.map(p=>`<item><g:id>${xml(p.id)}</g:id><title>${xml(p.title)}</title><description>${xml(p.description)}</description><link>${xml(p.link)}</link><g:image_link>${xml(p.image)}</g:image_link><g:availability>in_stock</g:availability><g:price>${xml(p.price)}</g:price></item>`).join("\n");
 return '<?xml version="1.0" encoding="UTF-8"?>\n<rss version="2.0" xmlns:g="http://base.google.com/ns/1.0"><channel><title>LEOGO Digital Market - Kenya</title><link>https://leogo.co.ke/</link><description>Approved, eligible LEOGO products with stable current KES prices.</description>\n'+nodes+'\n</channel></rss>\n';
}
